    "s.b2-02.6": "Se a hipótese tivesse sido provada, teria mudado a teoria completamente.",
    "s.b2-02.7": "A inteligência artificial pode analisar dados mais rápido do que qualquer humano.",
    "s.b2-02.8": "O avanço na pesquisa genética foi feito em um laboratório pequeno.",
    "s.b2-02.9": "Se hackers tivessem invadido o sistema, milhões de contas estariam em risco.",
    "s.b2-02.10": "A automação tornará muitos empregos obsoletos dentro de uma década.",
    "s.b2-02.11": "Os cientistas mediram as partículas com instrumentos de ponta.",
    "s.b2-02.12": "Se eu fosse cientista, estudaria como as células se reparam.",
    "d.b2-02.1": "Dra. Adler, a sua equipe anunciou um avanço na semana passada. O que exatamente vocês descobriram?",
    "d.b2-02.2": "Nós desenvolvemos um algoritmo que prevê como certas células reagem a novos medicamentos.",
    "d.b2-02.3": "Quão preciso ele é?",
    "d.b2-02.4": "Nos nossos experimentos, cerca de noventa por cento. Se os dados são bons, as previsões são confiáveis.",
    "d.b2-02.5": "O que aconteceria se um hospital confiasse nele e ele estivesse errado?",
    "d.b2-02.6": "É por isso que os médicos sempre tomarão a decisão final. A ferramenta apenas os apoia.",
    "d.b2-02.7": "Algumas pessoas temem que a inteligência artificial torne os cientistas obsoletos.",
    "d.b2-02.8": "Se isso fosse verdade, nós teríamos parado de contratar pesquisadores. Em vez disso, contratamos dez a mais.",
    "d.b2-02.9": "E a cibersegurança? Os dados dos pacientes são sensíveis.",
    "d.b2-02.10": "A menos que os dados sejam criptografados e armazenados localmente, nós não os usamos.",
    "d.b2-02.11": "O que vem a seguir para o laboratório?",
    "d.b2-02.12": "Se conseguirmos financiamento, realizaremos um teste maior na próxima primavera.",
    "m.b2-02": "Uma invenção que mudou o mundo é ... . Ela foi desenvolvida por ... em ... . Se não tivesse sido inventada, ... . Hoje ela é usada para ... . No futuro, se ..., ela poderia ... .",
