    "w.b2-03.efficiency": "a eficiência",
    "p.b2-03.1": "Os negócios vão de vento em popa.",
    "p.b2-03.2": "Nós estamos operando com prejuízo.",
    "p.b2-03.3": "Os preços foram às alturas.",
    "p.b2-03.4": "Vamos direto ao assunto.",
    "p.b2-03.5": "A empresa faliu no ano passado.",
    "p.b2-03.6": "A demanda supera a oferta no momento.",
    "p.b2-03.7": "É um investimento arriscado, mas os retornos podem ser altos.",
    "p.b2-03.8": "Por um lado..., por outro lado...",
    "p.b2-03.9": "Nós precisamos cortar custos em todas as áreas.",
    "p.b2-03.10": "O negócio não deu certo no último minuto.",
    "p.b2-03.11": "A longo prazo, vai compensar.",
    "p.b2-03.12": "Nossa participação de mercado dobrou.",
    "s.b2-03.1": "A inflação subiu drasticamente; como resultado, os consumidores gastaram menos.",
    "s.b2-03.2": "A startup lançou uma marca nova; no entanto, as vendas continuaram baixas.",
    "s.b2-03.3": "Embora a economia esteja crescendo, muitas famílias ainda passam dificuldades.",
    "s.b2-03.4": "A fusão vai reduzir custos; além disso, vai melhorar a eficiência.",
    "s.b2-03.5": "Em primeiro lugar, precisamos de investidores; em segundo, precisamos de um orçamento realista.",
    "s.b2-03.6": "O país exporta tecnologia, ao passo que importa a maior parte dos alimentos.",
    "s.b2-03.7": "Apesar da recessão, a empresa teve um pequeno lucro.",
    "s.b2-03.8": "A previsão aponta crescimento lento; portanto, devemos nos expandir com cuidado.",
    "s.b2-03.9": "Os preços das ações caíram depois da falência do maior fornecedor.",
    "s.b2-03.10": "A concorrência mantém os preços baixos, o que beneficia os consumidores no fim.",
    "s.b2-03.11": "A empreendedora financiou o projeto com as próprias economias.",
    "s.b2-03.12": "Finalmente, lembre-se de que todo negócio envolve algum risco.",
    "d.b2-03.1": "Obrigada pelo seu tempo. Nossa startup fabrica embalagens reutilizáveis para restaurantes.",
    "d.b2-03.2": "Interessante. Como está a demanda?",
    "d.b2-03.3": "Forte e crescente. Em primeiro lugar, novas regulamentações proíbem o plástico descartável; em segundo, os consumidores preferem marcas sustentáveis.",
    "d.b2-03.4": "No entanto, os seus custos de produção parecem altos. Como vocês vão ter lucro?",
    "d.b2-03.5": "No começo vamos operar com um pequeno prejuízo. Assim que nos expandirmos, a eficiência vai melhorar e os custos vão cair.",
    "d.b2-03.6": "E a concorrência? Há empresas maiores neste mercado.",
    "d.b2-03.7": "É verdade, mas elas importam os produtos, ao passo que nós fabricamos localmente e entregamos mais rápido.",
    "d.b2-03.8": "Quanto financiamento vocês estão buscando?",
    "d.b2-03.9": "Dois milhões, em troca de quinze por cento das ações.",
    "d.b2-03.10": "Isso é ambicioso. Além disso, a previsão supõe que não haverá recessão.",
    "d.b2-03.11": "Nós preparamos um segundo orçamento para uma economia mais lenta. Aqui está.",
    "d.b2-03.12": "Bom. Me envie o plano completo e conversamos na semana que vem.",
    "m.b2-03": "A economia de ... está atualmente ... . Em primeiro lugar, ... . Como resultado, ... . No entanto, ... . Além disso, ... . Portanto, a longo prazo ... .",
