    "p.b2-04.1": "Está aberto a interpretações.",
    "p.b2-04.2": "O romance foi um best-seller instantâneo.",
    "p.b2-04.3": "Eu não conseguia largar o livro.",
    "p.b2-04.4": "O quadro me deixou uma impressão profunda.",
    "p.b2-04.5": "A melodia ficou comigo por dias.",
    "p.b2-04.6": "Ela tem uma imaginação vívida.",
    "p.b2-04.7": "A exposição vale muito a visita.",
    "p.b2-04.8": "O que o autor quer dizer com isso?",
    "p.b2-04.9": "O final me pegou completamente de surpresa.",
    "p.b2-04.10": "Arte é uma questão de gosto.",
    "p.b2-04.11": "A letra é mais importante do que a música.",
    "s.b2-04.1": "A publicação do primeiro romance dela mudou a sua vida.",
    "s.b2-04.2": "O retrato da pobreza no filme é dolorosamente realista.",
    "s.b2-04.3": "A interpretação da escultura pelo curador surpreendeu muitos visitantes.",
    "s.b2-04.4": "A solidão do protagonista é o tema central do romance.",
    "s.b2-04.5": "A composição da sinfonia levou quase uma década ao compositor.",
    "s.b2-04.6": "O poeta usa o mar como metáfora da memória.",
    "s.b2-04.7": "A chegada do maestro ao palco foi recebida com fortes aplausos.",
    "s.b2-04.8": "A arte abstrata exige a participação ativa do espectador.",
    "s.b2-04.9": "A falta de confiabilidade do narrador dá tensão à história.",
    "s.b2-04.10": "O retrato revela a tristeza por trás do sorriso do rei.",
    "s.b2-04.11": "O dramaturgo encontrou inspiração em uma antiga tragédia grega.",
    "s.b2-04.12": "A decisão da galeria de expor artistas jovens foi amplamente elogiada.",
    "d.b2-04.1": "Então, o que todos acharam do romance?",
    "d.b2-04.2": "Sinceramente, eu achei o protagonista difícil de gostar, mas a escrita é linda.",
    "d.b2-04.3": "Eu concordo quanto à escrita. O uso de metáforas pela autora é notável.",
    "d.b2-04.4": "O rio que sempre volta, por exemplo. É uma metáfora do tempo?",
    "d.b2-04.5": "Essa é uma interpretação. Eu li como a culpa do narrador.",
    "d.b2-04.6": "Interessante. O tema da culpa realmente percorre o livro inteiro.",
    "d.b2-04.7": "Você sabia que está sendo adaptado para o palco por um dramaturgo conhecido?",
    "d.b2-04.8": "Sério? Eu me pergunto como vão retratar as cenas de sonho.",
    "d.b2-04.9": "Provavelmente com música. A autora disse que o ritmo era mais importante para ela do que o enredo.",
    "d.b2-04.10": "Isso explica por que em alguns trechos parece poesia.",
    "d.b2-04.11": "Vamos escolher algo mais leve para o mês que vem?",
    "d.b2-04.12": "Sim, por favor. Uma comédia, ou pelo menos não outra tragédia.",
    "m.b2-04": "A exposição oferece um retrato raro de ... . A escolha de ... pelo curador cria ... . De particular interesse é ... . A combinação de ... e ... resulta em ... . No geral, ... .",
