    "p.b2-05.1": "Inocente até que se prove o contrário.",
    "p.b2-05.2": "Ele negou todas as acusações.",
    "p.b2-05.3": "O júri chegou a um veredicto.",
    "p.b2-05.4": "Eu vou te levar ao tribunal.",
    "p.b2-05.5": "Ela foi multada por estacionar ilegalmente.",
    "p.b2-05.6": "Todos são iguais perante a lei.",
    "p.b2-05.7": "O caso foi arquivado por falta de provas.",
    "p.b2-05.8": "Isso é sequer legal?",
    "p.b2-05.9": "O advogado instou o seu cliente a permanecer em silêncio.",
    "p.b2-05.10": "Você tem o direito de permanecer em silêncio.",
    "p.b2-05.11": "O réu foi considerado inocente.",
    "s.b2-05.1": "O réu alegou que tinha estado em casa naquela noite.",
    "s.b2-05.2": "A testemunha admitiu que não tinha visto o rosto do homem.",
    "s.b2-05.3": "O juiz perguntou à testemunha se ela reconhecia o réu.",
    "s.b2-05.4": "O advogado insistiu que o seu cliente era inocente de fraude.",
    "s.b2-05.5": "A polícia alertou os moradores para não deixarem as portas destrancadas.",
    "s.b2-05.6": "A empresa foi processada por violar os regulamentos de privacidade.",
    "s.b2-05.7": "O ministro negou que a nova legislação limitaria quaisquer direitos.",
    "s.b2-05.8": "O tribunal decidiu que a proibição do protesto era inconstitucional.",
    "s.b2-05.9": "Depois do veredicto, o réu anunciou que iria recorrer.",
    "s.b2-05.10": "Todo cidadão tem direito a um julgamento justo segundo a constituição.",
    "s.b2-05.11": "A investigação revelou provas de discriminação contra trabalhadores mais velhos.",
    "s.b2-05.12": "A repórter disse que o homem tinha sido condenado por um crime grave.",
    "d.b2-05.1": "Noa, você estava no tribunal hoje de manhã. O que aconteceu?",
    "d.b2-05.2": "O julgamento começou com a promotoria apresentando novas provas contra o réu.",
    "d.b2-05.3": "O que o réu disse?",
    "d.b2-05.4": "Ele insistiu que era inocente e alegou que os documentos tinham sido falsificados.",
    "d.b2-05.5": "Alguma testemunha depôs?",
    "d.b2-05.6": "Sim. Uma ex-funcionária admitiu que tinha assinado os contratos sem lê-los.",
    "d.b2-05.7": "Como o juiz reagiu?",
    "d.b2-05.8": "Ele advertiu os dois lados para não falarem com a imprensa e perguntou se mais provas seriam apresentadas.",
    "d.b2-05.9": "Espera-se um veredicto em breve?",
    "d.b2-05.10": "Os advogados me disseram que o julgamento provavelmente duraria mais três semanas.",
