    "w.b2-06.to-flee": "fugir",
    "p.b2-06.1": "É um problema global que precisa de uma solução global.",
    "p.b2-06.2": "Nós precisamos aumentar a conscientização.",
    "p.b2-06.3": "Milhões não têm acesso a água limpa.",
    "p.b2-06.4": "Pense globalmente, aja localmente.",
    "p.b2-06.5": "O abismo entre ricos e pobres está aumentando.",
    "p.b2-06.6": "O tempo está se esgotando.",
    "p.b2-06.7": "Toda doação conta, por menor que seja.",
    "p.b2-06.8": "As negociações terminaram sem acordo.",
    "p.b2-06.9": "É uma gota no oceano.",
    "p.b2-06.10": "Nós não podemos nos dar ao luxo de ignorar isso.",
    "p.b2-06.11": "Prevenir é mais barato do que remediar.",
    "s.b2-06.1": "Enfrentando uma seca severa, o governo pediu ajuda humanitária.",
    "s.b2-06.2": "Assinado em 2015, o tratado visa limitar o aquecimento global.",
    "s.b2-06.3": "Doar para uma instituição de caridade é uma forma de enfrentar a desigualdade.",
    "s.b2-06.4": "Tendo fugido do conflito, as famílias agora vivem em abrigos temporários.",
    "s.b2-06.5": "O desmatamento destrói a biodiversidade, afetando milhões de espécies.",
    "s.b2-06.6": "As sanções impostas no ano passado tiveram consequências sérias.",
    "s.b2-06.7": "Espalhando-se rapidamente pelas fronteiras, a pandemia afetou todos os países.",
    "s.b2-06.8": "Os ativistas esperam que aumentar a conscientização leve a uma mudança real.",
    "s.b2-06.9": "O embaixador alertou que a diplomacia sozinha não acabaria com o conflito.",
    "s.b2-06.10": "Melhorar a infraestrutura é essencial para o desenvolvimento das regiões pobres.",
    "s.b2-06.11": "As populações vulneráveis sofrem mais com os efeitos da globalização.",
    "s.b2-06.12": "Sem acesso à educação, as crianças permanecem presas na pobreza.",
    "d.b2-06.1": "Dr. Mansour, quão séria é a ameaça do aquecimento global hoje?",
    "d.b2-06.2": "Extremamente séria. Tendo estudado os dados por vinte anos, eu posso dizer que as mudanças são mais rápidas do que o previsto.",
    "d.b2-06.3": "Yonatan, a sua organização se concentra no desmatamento. Por quê?",
    "d.b2-06.4": "Porque derrubar florestas destrói a biodiversidade e libera carbono ao mesmo tempo.",
    "d.b2-06.5": "O que as pessoas comuns podem fazer?",
    "d.b2-06.6": "Doar ajuda, mas aumentar a conscientização e votar nas políticas certas importa mais.",
    "d.b2-06.7": "Eu concordo. Os governos respondem à pressão, como vimos com o tratado assinado no ano passado.",
    "d.b2-06.8": "Alguns argumentam que sanções contra países poluidores seriam mais eficazes.",
    "d.b2-06.9": "Impor sanções sem oferecer ajuda geralmente prejudica as populações mais vulneráveis.",
    "d.b2-06.10": "Exatamente. Diplomacia e desenvolvimento devem andar juntos.",
    "d.b2-06.11": "Há algum motivo para esperança?",
    "d.b2-06.12": "Sim. A energia renovável está se espalhando mais rápido do que qualquer um esperava dez anos atrás.",
    "m.b2-06": "Tendo identificado ... como uma grande ameaça, nós propomos ... . Financiado por ..., o projeto iria ... . Trabalhando com as comunidades locais, nós pretendemos ... . Reduzir ... também vai ... .",
