    "p.c1-01.1": "É um ponto justo, mas deixa escapar o quadro geral.",
    "p.c1-01.2": "É verdade que as provas são limitadas.",
    "p.c1-01.3": "Deixe-me fazer o papel de advogado do diabo por um momento.",
    "p.c1-01.4": "Eu entendo o seu ponto, mas não estou convencido.",
    "p.c1-01.5": "Correlação não implica causalidade.",
    "p.c1-01.6": "Você está se contradizendo.",
    "p.c1-01.7": "Vamos concordar em discordar.",
    "p.c1-01.8": "O ônus da prova é seu.",
    "p.c1-01.9": "Esse argumento simplesmente não se sustenta.",
    "p.c1-01.10": "Com todo o respeito, isso não vem ao caso.",
    "p.c1-01.11": "O que importa aqui é o efeito a longo prazo.",
    "p.c1-01.12": "No balanço geral, os benefícios superam os custos.",
    "s.c1-01.1": "Embora a afirmação dela pareça persuasiva, a premissa por trás dela é falsa.",
    "s.c1-01.2": "É verdade que a política é controversa; ainda assim, ela reduziu a pobreza.",
    "s.c1-01.3": "É a falta de provas que mina todo o argumento dele.",
    "s.c1-01.4": "Eu concedo esse ponto, ao passo que a conclusão eu ainda rejeito.",
    "s.c1-01.5": "Uma posição coerente reconhece os contra-argumentos em vez de ignorá-los.",
    "s.c1-01.6": "Mesmo que suponhamos boas intenções, o viés afeta toda decisão.",
    "s.c1-01.7": "O que torna uma falácia perigosa é que ela parece lógica.",
    "s.c1-01.8": "Ela refutou a afirmação do oponente com uma única estatística.",
    "s.c1-01.9": "Defender a mudança é fácil; justificar os seus custos é mais difícil.",
    "s.c1-01.10": "Há uma contradição clara entre a premissa e a conclusão dele.",
    "s.c1-01.11": "O consenso científico não significa que o debate esteja encerrado para sempre.",
    "s.c1-01.12": "Ao contrário, os dados fortalecem a afirmação em vez de enfraquecê-la.",
    "d.c1-01.1": "Omri, você defende o voto obrigatório. Sua afirmação de abertura, por favor.",
    "d.c1-01.2": "A democracia depende da participação. Quando metade da população fica em casa, o resultado reflete uma amostra enviesada, não a vontade pública.",
    "d.c1-01.3": "Leah, sua resposta.",
    "d.c1-01.4": "É verdade que a baixa participação é um problema. Ainda assim, forçar as pessoas a votar mina justamente a liberdade que as eleições deveriam proteger.",
    "d.c1-01.5": "Eu concedo que a liberdade importa. No entanto, nós já aceitamos impostos obrigatórios e o serviço de júri, ao passo que votar leva dez minutos.",
    "d.c1-01.6": "Essa é uma falsa comparação. Os impostos financiam serviços; um voto forçado produz escolhas aleatórias de eleitores desinformados.",
    "d.c1-01.7": "Omri, como você responde ao contra-argumento sobre eleitores desinformados?",
    "d.c1-01.8": "O que as evidências da Austrália mostram é que o voto obrigatório na verdade aumenta o conhecimento político ao longo do tempo.",
    "d.c1-01.9": "Um país dificilmente é um consenso. Além disso, você está supondo que o efeito seria o mesmo aqui.",
    "d.c1-01.10": "É verdade, mas a alternativa, não fazer nada, claramente fracassou.",
    "d.c1-01.11": "Declarações finais. Leah primeiro.",
    "d.c1-01.12": "No balanço geral, os custos para a liberdade superam os benefícios incertos. Persuadam as pessoas a votar; não as forcem.",
    "m.c1-01": "Afirma-se frequentemente que ... . É verdade que ... . Ainda assim, o que as evidências mostram é que ... . Ao passo que os opositores argumentam ..., isso ignora ... . No balanço geral, ... .",
