    "w.c1-02.rational": "racional",
    "p.c1-02.1": "Está tudo na sua cabeça.",
    "p.c1-02.2": "Velhos hábitos custam a morrer.",
    "p.c1-02.3": "Ela tende a pensar demais nas coisas.",
    "p.c1-02.4": "Presumivelmente, o estresse teve um papel.",
    "p.c1-02.5": "Ele devia estar sob uma pressão enorme.",
    "p.c1-02.6": "Até certo ponto, todos nós somos enviesados.",
    "p.c1-02.7": "Eu não consegui resistir à tentação.",
    "p.c1-02.8": "Parece que recompensas funcionam melhor do que punições.",
    "p.c1-02.9": "Não tire conclusões precipitadas.",
    "p.c1-02.10": "Pode-se argumentar que a personalidade é moldada mais pelo ambiente do que pelos genes.",
    "p.c1-02.11": "Você não podia saber disso na época.",
    "s.c1-02.1": "Pessoas com autoestima alta podem lidar melhor com críticas.",
    "s.c1-02.2": "A procrastinação parece estar ligada à ansiedade, e não à preguiça.",
    "s.c1-02.3": "Pessoas extrovertidas tendem a buscar recompensas em situações sociais.",
    "s.c1-02.4": "O sujeito pode ter reprimido a memória por anos.",
    "s.c1-02.5": "A pressão do grupo poderia explicar, até certo ponto, por que os adolescentes correm riscos.",
    "s.c1-02.6": "Pode-se argumentar que a nossa percepção é moldada por preconceitos subconscientes.",
    "s.c1-02.7": "Os incentivos presumivelmente só funcionam quando a meta parece alcançável.",
    "s.c1-02.8": "A resiliência parece depender em parte dos relacionamentos na infância.",
    "s.c1-02.9": "Ele não pode ter agido por impulso; o plano era detalhado demais.",
    "s.c1-02.10": "A terapia pode ajudar os pacientes a reconhecer a manipulação nos seus relacionamentos.",
    "s.c1-02.11": "A intuição não é sempre irracional; frequentemente ela reflete a experiência.",
    "s.c1-02.12": "Uma mentalidade de crescimento aparentemente melhora o desempenho cognitivo das crianças.",
    "d.c1-02.1": "Dra. Peretz, por que pessoas inteligentes tomam decisões irracionais?",
    "d.c1-02.2": "Inteligência e racionalidade são traços diferentes. Pessoas inteligentes podem simplesmente ser melhores em justificar os seus impulsos.",
    "d.c1-02.3": "Então a força de vontade não é a resposta?",
    "d.c1-02.4": "Só até certo ponto. A força de vontade tende a se esgotar; um ambiente de apoio parece importar mais.",
    "d.c1-02.5": "A sua pesquisa sobre procrastinação surpreendeu muita gente.",
    "d.c1-02.6": "Presumivelmente porque supomos que os procrastinadores são preguiçosos. Nossos dados sugerem que eles frequentemente são perfeccionistas ansiosos.",
    "d.c1-02.7": "As redes sociais poderiam estar piorando isso?",
    "d.c1-02.8": "Talvez. A comparação constante parece reduzir a autoestima, especialmente entre adolescentes expostos à pressão do grupo.",
    "d.c1-02.9": "Há alguma coisa que construa resiliência de forma confiável?",
    "d.c1-02.10": "Pode-se argumentar que a empatia de um adulto de confiança. As evidências não são conclusivas, mas são consistentes.",
    "d.c1-02.11": "Algum conselho final para os nossos leitores?",
    "d.c1-02.12": "Trate a sua intuição como uma hipótese, não como um veredicto. Depois, verifique.",
    "m.c1-02": "A pesquisa sugere que ... tende a ... . Isso pode ser porque ... . Até certo ponto, ... . Parece que ..., embora as evidências sejam ... . Presumivelmente, ... .",
