    "p.c1-03.1": "A história se repete.",
    "p.c1-03.2": "Aqueles que esquecem o passado estão condenados a repeti-lo.",
    "p.c1-03.3": "Marcou um ponto de virada na história europeia.",
    "p.c1-03.4": "Em retrospecto, o colapso era inevitável.",
    "p.c1-03.5": "Os fins justificam os meios, ou não?",
    "p.c1-03.6": "Penso, logo existo.",
    "p.c1-03.7": "Conhece-te a ti mesmo.",
    "p.c1-03.8": "Isso levanta mais perguntas do que respostas.",
    "p.c1-03.9": "A história é escrita pelos vencedores.",
    "p.c1-03.10": "Não só o império caiu, mas a sua língua também desapareceu.",
    "p.c1-03.11": "Existe tal coisa como o livre-arbítrio?",
    "s.c1-03.1": "Nunca antes um império tinha colapsado tão rápida e tão completamente.",
    "s.c1-03.2": "Não só a revolução acabou com a escravidão, mas também redefiniu a cidadania.",
    "s.c1-03.3": "Como os arquivos foram destruídos, os historiadores precisam interpretar fragmentos.",
    "s.c1-03.4": "Só depois da independência o país começou a escrever a sua própria história.",
    "s.c1-03.5": "Os filósofos antigos refletiam sobre se a virtude podia ser ensinada.",
    "s.c1-03.6": "Embora a razão guie a ética, a emoção frequentemente decide a nossa moral.",
    "s.c1-03.7": "Se o rei não tivesse sido derrubado, a era dos impérios poderia ter continuado.",
    "s.c1-03.8": "O ceticismo, longe de negar o conhecimento, pergunta como o justificamos.",
    "s.c1-03.9": "Tão poderosa era a ideologia que milhões a aceitaram sem questionar.",
    "s.c1-03.10": "O paradoxo do livre-arbítrio é que nos sentimos livres, mas agimos de forma previsível.",
    "s.c1-03.11": "Toda civilização que conquistou os seus vizinhos acabou enfrentando o mesmo destino.",
    "s.c1-03.12": "O que os filósofos chamam de existência, os historiadores chamam de contexto.",
    "d.c1-03.1": "Por que o Império Romano colapsou? Shai, vamos começar com você.",
    "d.c1-03.2": "Tradicionalmente, os historiadores culpavam as invasões. Não só as fronteiras eram longas demais, mas o exército também estava exausto.",
    "d.c1-03.3": "Mor, você discorda?",
    "d.c1-03.4": "Em parte. Se a economia estivesse saudável, o império poderia ter sobrevivido às invasões, como já tinha feito antes.",
    "d.c1-03.5": "Então você interpreta o colapso como econômico, e não militar?",
    "d.c1-03.6": "Sim. A escravidão tornou a inovação desnecessária, e quando a conquista parou, o fornecimento de escravos também parou.",
    "d.c1-03.7": "Mas essa é uma leitura moderna. Os próprios escritores antigos culpavam uma perda de virtude.",
    "d.c1-03.8": "O que levanta uma questão filosófica: uma civilização pode decair moralmente?",
    "d.c1-03.9": "Só se supusermos que a moral é mais do que ideologia, o que os céticos negariam.",
    "d.c1-03.10": "No entanto, sem alguma ética compartilhada, nenhuma sociedade se mantém unida por muito tempo.",
    "d.c1-03.11": "Excelente. Para a semana que vem, leiam as fontes do arquivo e decidam qual ponto de virada vocês consideram mais convincente.",
    "d.c1-03.12": "E se a queda foi inevitável, ou se o livre-arbítrio teve um papel.",
    "m.c1-03": "Raramente uma questão dividiu os pensadores tão profundamente quanto ... . Ao passo que alguns argumentam que ..., outros sustentam que ... . Não só isso importa para ..., mas também ... . Só por meio de ... podemos ... .",
