    "s.c1-04.8": "Um esquema conciso é preparado antes que o primeiro rascunho seja escrito.",
    "s.c1-04.9": "O memorando esclarece o escopo do projeto para todos os departamentos.",
    "s.c1-04.10": "Parafrasear transmite a ideia do autor sem copiar a redação.",
    "s.c1-04.11": "Uma revisão cuidadosa é considerada essencial antes da submissão.",
    "s.c1-04.12": "A bibliografia lista todas as fontes que foram citadas na tese.",
    "d.c1-04.1": "Nir, eu li o seu rascunho. A seção de metodologia é forte, mas a introdução é longa demais.",
    "d.c1-04.2": "Eu temia isso. Devo mover o contexto histórico para um apêndice?",
    "d.c1-04.3": "Em parte. Resuma a história em um parágrafo e cite as fontes principais em vez de descrevê-las.",
    "d.c1-04.4": "Entendido. E o capítulo de resultados?",
    "d.c1-04.5": "Os dados estão bem apresentados, mas várias frases são ambíguas. Por exemplo, a palavra significativo não está clara aqui.",
