    "d.c1-04.7": "Bom. Além disso, a seção de implicações faz afirmações que vão além do escopo dos seus dados.",
    "d.c1-04.8": "Você quer dizer a parte sobre política nacional?",
    "d.c1-04.9": "Exatamente. Ou modere essas afirmações ou as remova. Diga o que os resultados indicam, não o que você espera que eles provem.",
    "d.c1-04.10": "Eu vou parafrasear a seção e suavizar o tom. Mais alguma coisa?",
